-- Blog posts, managed by administrators. A blog is public when
--   status = 'publish' AND deleted_at IS NULL AND published_at <= now();
-- a future published_at is a scheduled post. The application sets published_at when publishing, and
-- the database requires it for published rows so the public query needs no NULL branch.
-- Soft-deleted through deleted_at.
-- Rollback: db/rollback/U202610251810__create_blogs.sql

SET LOCAL lock_timeout = '5s';

CREATE TABLE blogs (
    id                 BIGSERIAL PRIMARY KEY,
    title              VARCHAR(255)  NOT NULL,
    -- Generated by the application from the title. Unique across soft-deleted rows too, so an old
    -- blog URL never points at a different post.
    slug               VARCHAR(255)  NOT NULL,
    -- Object storage key of the feature image, never a public URL or client filename.
    feature_image      TEXT,
    -- Nullable so a draft can be saved before a category is chosen. RESTRICT: categories are
    -- soft-deleted; a hard delete must not silently detach or remove posts.
    category_id        BIGINT        REFERENCES blog_categories (id) ON DELETE RESTRICT,
    short_description  TEXT,
    -- Rich text / HTML from the admin editor; sanitize with an allow-list before rendering.
    content            TEXT,
    status             VARCHAR(20)   NOT NULL DEFAULT 'draft',
    meta_title         VARCHAR(255),
    meta_description   TEXT,
    -- JSON array of tag strings, e.g. ["home-loans", "investment"].
    tags               JSONB,
    published_at       TIMESTAMPTZ,
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    deleted_at         TIMESTAMPTZ,

    CONSTRAINT uq_blogs_slug UNIQUE (slug),
    CONSTRAINT chk_blogs_title_not_blank CHECK (btrim(title) <> ''),
    CONSTRAINT chk_blogs_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT chk_blogs_status CHECK (status IN ('draft', 'publish')),
    CONSTRAINT chk_blogs_published_at CHECK (status <> 'publish' OR published_at IS NOT NULL),
    -- Relative object key: no leading slash, no "..", no scheme (same rule as banners).
    CONSTRAINT chk_blogs_feature_image
        CHECK (feature_image ~ '^[A-Za-z0-9][A-Za-z0-9/_.-]*$' AND feature_image NOT LIKE '%..%'),
    CONSTRAINT chk_blogs_tags
        CHECK (jsonb_typeof(tags) = 'array' AND NOT jsonb_path_exists(tags, '$[*] ? (@.type() != "string")'))
);

-- FK check when a category row is deleted, and the admin category filter (all statuses).
CREATE INDEX idx_blogs_category_id ON blogs (category_id);
-- Admin list filtered by status, newest first.
CREATE INDEX idx_blogs_status_created_at ON blogs (status, created_at) WHERE deleted_at IS NULL;
-- Public feed: published_at <= now() ORDER BY published_at DESC. Partial, so drafts and deleted
-- posts never bloat it; scheduled posts are skipped by the range condition.
CREATE INDEX idx_blogs_public_published_at ON blogs (published_at DESC, id DESC)
    WHERE status = 'publish' AND deleted_at IS NULL;
-- Public feed of one category.
CREATE INDEX idx_blogs_public_category_published_at ON blogs (category_id, published_at DESC)
    WHERE status = 'publish' AND deleted_at IS NULL;

COMMENT ON COLUMN blogs.slug IS 'Application-generated URL key; never reused, even after soft delete';
COMMENT ON COLUMN blogs.status IS 'draft = hidden; publish = public once published_at has passed';
COMMENT ON COLUMN blogs.published_at IS 'Actual or scheduled publication time; required when status = publish';
COMMENT ON COLUMN blogs.content IS 'Untrusted HTML; sanitize with an allow-list before rendering';
COMMENT ON COLUMN blogs.deleted_at IS 'Soft-delete timestamp; NULL = not deleted';
